<script setup lang="ts">import { computed, ref } from 'vue';import { useRoute } from 'vue-router';const route=useRoute();const isDrawerOpen=ref(false);const title=computed(()=>`知识条目 #${route.params.id}`);const citations=ref([{title:'来源文档',content:'这里展示命中的原始片段、段落位置和来源链接。'}]);</script>
<template><header class="page-head"><div><el-button text @click="$router.back()">← 返回</el-button><h1 class="page-title">{{title}}</h1></div><el-button type="primary" @click="isDrawerOpen=true">查看引用</el-button></header><el-card><p class="answer">知识详情页展示服务器返回的结构化正文、元信息和相关知识。移动端的来源内容通过抽屉呈现，避免挤压主阅读区域。</p></el-card><el-drawer v-model="isDrawerOpen" title="引用来源" direction="rtl"><el-card v-for="item in citations" :key="item.title"><h3>{{item.title}}</h3><p>{{item.content}}</p></el-card></el-drawer></template>
